+      res.status(409).json({
+        error: `Claim ${claimId} cannot be withdrawn from status "${result.currentStatus}"`,
+      });
+      return;
+    }
+
+    console.log('Claim withdrawn:', JSON.stringify(redact(result.claim)));
+    res.status(200).json(result.claim);
+  }
